import java.io.*;
import java.util.*;

public class Main {
    private static int countOptions(char[] s, char x) {
        for(int i = 0; i < s.length; i++) {
            if(s[i] == 'X') s[i] = x;
        }
        if(s[0] == '0') return 0;
        int ways = 1;
        boolean firstX = true;
        for(int i = 0; i < s.length; i++) {
            if(s[i] == '_') {
                ways *= (i == 0) ? 9 : 10;
            } else if(s[i] == 'X' && firstX) {
                ways *= (i == 0) ? 9 : 10;
                firstX = false;
            }
        }
        return ways;
    }
    private static boolean checkValidity(char[] s, char a, char b) {
        if(s[s.length-2] >= '0' && s[s.length-2] <= '9' && s[s.length-2] != a) return false;
        if(s[s.length-1] >= '0' && s[s.length-1] <= '9' && s[s.length-1] != b) return false;
        if(s[s.length-2] == 'X' && s[s.length-1] == 'X' && a != b) return false;
        return true;
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(new OutputStreamWriter(System.out));
        char[] s = br.readLine().toCharArray();
        if(s.length < 2) {
            pw.println((s[0] == '0' || s[0] == '_' || s[0] == 'X') ? 1 : 0);
        } else {
            int total = 0;
            if(checkValidity(s, '0', '0')) {
                char[] t = s.clone();
                t[t.length-2] = '0';
                t[t.length-1] = '0';
                if(s[s.length-2] == 'X') {
                    total += countOptions(t, t[t.length-2]);
                } else if(s[s.length-1] == 'X') {
                    total += countOptions(t, t[t.length-1]);
                } else {
                    total += countOptions(t, 'X');
                }
            }
            if(checkValidity(s, '2', '5')) {
                char[] t = s.clone();
                t[t.length-2] = '2';
                t[t.length-1] = '5';
                if(s[s.length-2] == 'X') {
                    total += countOptions(t, t[t.length-2]);
                } else if(s[s.length-1] == 'X') {
                    total += countOptions(t, t[t.length-1]);
                } else {
                    total += countOptions(t, 'X');
                }
            }
            if(checkValidity(s, '5', '0')) {
                char[] t = s.clone();
                t[t.length-2] = '5';
                t[t.length-1] = '0';
                if(s[s.length-2] == 'X') {
                    total += countOptions(t, t[t.length-2]);
                } else if(s[s.length-1] == 'X') {
                    total += countOptions(t, t[t.length-1]);
                } else {
                    total += countOptions(t, 'X');
                }
            }
            if(checkValidity(s, '7', '5')) {
                char[] t = s.clone();
                t[t.length-2] = '7';
                t[t.length-1] = '5';
                if(s[s.length-2] == 'X') {
                    total += countOptions(t, t[t.length-2]);
                } else if(s[s.length-1] == 'X') {
                    total += countOptions(t, t[t.length-1]);
                } else {
                    total += countOptions(t, 'X');
                }
            }
            pw.println(total);
        }
        br.close();
        pw.close();
    }
}
